/*
 * Inference backend interface. One backend is linked per MCU path:
 *   STM32H743 path : backends/ai_backend_tflm.cc  (TensorFlow Lite Micro + CMSIS-NN, int8 model)
 *   GD32H759 path  : backends/ai_backend_gd32.c   (code generated by GigaDevice GD32 Embedded AI)
 * ai_health.c (window, rules, hybrid decision, alerts) is identical on both.
 */
#ifndef AI_BACKEND_H
#define AI_BACKEND_H

#include "pal_types.h"

typedef struct {
    const char *name;
    pal_status_t (*init)(void);
    /* x: normalised window, row-major [AI_WINDOW][AI_N_FEAT], oldest sample first.
     * probs: AI_N_CLASS class probabilities. Each backend quantises internally as its model needs. */
    pal_status_t (*infer)(const float *x, float *probs);
} ai_backend_t;

const ai_backend_t *ai_backend_get(void);

#endif
